export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    let path = url.pathname;

    // 1. Explicit 301 Redirect Check (exact raw path)
    if (REDIRECTS[path]) {
      return Response.redirect(url.origin + REDIRECTS[path], 301);
    }

    // Normalize trailing slash and optional .html extension
    let norm = path;
    if (norm.length > 1 && norm.endsWith('/')) {
      norm = norm.slice(0, -1);
    }
    if (norm.length > 5 && norm.endsWith('.html')) {
      norm = norm.slice(0, -5);
    }
    if (norm === '') norm = '/';

    // 2. Explicit 301 Redirect Check (normalized path)
    if (REDIRECTS[norm]) {
      return Response.redirect(url.origin + REDIRECTS[norm], 301);
    }

    // 3. Check routes
    const asset = ASSET_ROUTES[norm] || ASSET_ROUTES[path] || ASSET_ROUTES[url.pathname];

    if (asset) {
      const cacheControl = (path === '/sw.js' || url.pathname === '/sw.js')
        ? 'no-cache, no-store, must-revalidate'
        : 'public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800';

      if (asset.base64) {
        const bin = atob(asset.content);
        const len = bin.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = bin.charCodeAt(i);
        }
        return new Response(bytes.buffer, {
          status: 200,
          headers: {
            'Content-Type': asset.type,
            'Cache-Control': cacheControl,
            'X-Powered-By': 'agy_auto_site / Cloudflare Workers',
            'Access-Control-Allow-Origin': '*'
          }
        });
      }

      return new Response(asset.content, {
        status: 200,
        headers: {
          'Content-Type': asset.type,
          'Cache-Control': cacheControl,
          'X-Powered-By': 'agy_auto_site / Cloudflare Workers',
          'Access-Control-Allow-Origin': '*',
          'Service-Worker-Allowed': '/'
        }
      });
    }

    // 404 Fallback
    const notFoundHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8"><title>Page Not Found | 404</title>
  <script src="https://cdn.tailwindcss.com"></script>
</head>
<body class="bg-slate-900 text-white min-h-screen flex flex-col items-center justify-center p-4">
  <div class="text-center max-w-md">
    <h1 class="text-6xl font-black text-indigo-500 mb-4">404</h1>
    <h2 class="text-2xl font-bold mb-2">Page Not Found</h2>
    <p class="text-slate-400 mb-6">The requested page does not exist or has been relocated.</p>
    <a href="/" class="px-6 py-3 bg-indigo-600 hover:bg-indigo-700 rounded-xl font-semibold transition">Back to Homepage</a>
  </div>
</body>
</html>`;

    return new Response(notFoundHtml, {
      status: 404,
      headers: {
        'Content-Type': 'text/html; charset=utf-8'
      }
    });
  }
};
